package com.aistock.prediction.question;
import com.aistock.common.BusinessException;import com.aistock.prediction.maas.MaasOperationGate;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.util.*;import java.time.*;import java.security.*;import java.nio.charset.StandardCharsets;import static com.aistock.prediction.maas.MaasOperationGate.*;
public final class QuestionRepository {
 private static final String KIND="STOCK_QUESTION";private final JdbcTemplate jdbc;private final ObjectMapper m;private final TransactionTemplate tx;private final MaasOperationGate gate;
 public record Claim(boolean execute,JsonNode receipt){}
 public QuestionRepository(JdbcTemplate j,ObjectMapper m){jdbc=j;this.m=m;gate=new MaasOperationGate(j);tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(j.getDataSource())));tx.setTimeout(5);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);}
 public JsonNode replay(UUID u,QuestionInput in,Instant now){return tx.execute(s->{var rows=ops(in.operationId());if(rows.isEmpty())return null;check(rows.get(0),u,in);gate.lock(now);return receipt(ops(in.operationId()).get(0),now);});}
 public Claim claim(UUID u,QuestionInput in,QuestionFacts.Facts facts,Instant now){return tx.execute(s->{var prior=replay(u,in,now);if(prior!=null)return new Claim(false,prior);owned(u,in.analysisId());gate.lock(now);prior=replay(u,in,now);if(prior!=null)return new Claim(false,prior);var saved=jdbc.queryForList("select answer_id from stock_question_result where user_id=? and analysis_id=? and context_hash=?",String.class,u.toString(),in.analysisId().toString(),facts.hash());String id=saved.isEmpty()?null:saved.get(0);if(id==null)gate.lockAndAcquire(KIND,in.operationId(),now);jdbc.update("insert into stock_question_operation(operation_id,user_id,analysis_id,question,request_hash,context_hash,context_json,state,answer_id,created_at,lease_until,finished_at) values(?,?,?,?,?,?,?,?,?,?,?,?)",in.operationId().toString(),u.toString(),in.analysisId().toString(),in.question(),hash(in),facts.hash(),json(facts.context()),id==null?"RUNNING":"SUCCEEDED",id,ts(now),ts(now.plusSeconds(50)),id==null?null:ts(now));return new Claim(id==null,receipt(ops(in.operationId()).get(0),now));});}
 public JsonNode complete(UUID op,QuestionAnswerTemplate.Answer answer,String error,Instant now){return tx.execute(s->{var slot=gate.lock(now);var rows=ops(op);if(rows.isEmpty())throw missing();var r=rows.get(0);if(!"RUNNING".equals(r.get("state")))return receipt(r,now);if(!gate.owns(slot,KIND,op))throw conflict();String id=null,code=error;if(code==null){if(answer==null)throw QuestionFacts.invalid();id=UUID.randomUUID().toString();jdbc.update("insert into stock_question_result(answer_id,user_id,analysis_id,question,question_hash,context_hash,context_json,status,topic,paragraphs_json,created_at) values(?,?,?,?,?,?,?,?,?,?,?)",id,r.get("user_id"),r.get("analysis_id"),r.get("question"),sha(r.get("question").toString().getBytes(StandardCharsets.UTF_8)),r.get("context_hash"),r.get("context_json"),answer.status(),answer.topic(),json(answer.paragraphs()),ts(now));}else if(!code.matches("[A-Z0-9_]{1,64}"))code="AI_UNAVAILABLE";jdbc.update("update stock_question_operation set state=?,answer_id=?,error_code=?,finished_at=? where operation_id=?",id==null?"FAILED":"SUCCEEDED",id,code,ts(now),op.toString());gate.release(KIND,op);return receipt(ops(op).get(0),now);});}
 public JsonNode operation(UUID u,UUID op,Instant now){var rows=jdbc.queryForList("select * from stock_question_operation where operation_id=? and user_id=?",op.toString(),u.toString());if(rows.isEmpty())throw missing();return receipt(rows.get(0),now);}
 public JsonNode get(UUID u,UUID id){var rows=jdbc.queryForList("select * from stock_question_result where answer_id=? and user_id=?",id.toString(),u.toString());if(rows.isEmpty())throw missing();return result(rows.get(0));}
 public JsonNode list(UUID u,UUID id,int page,Instant now){owned(u,id);var root=m.createObjectNode().put("page",page).put("total",jdbc.queryForObject("select count(*) from stock_question_result where user_id=? and analysis_id=?",Long.class,u.toString(),id.toString()));var items=root.putArray("items");jdbc.queryForList("select * from stock_question_result where user_id=? and analysis_id=? order by sequence_id desc limit 10 offset ?",u.toString(),id.toString(),(page-1)*10).forEach(r->items.add(result(r)));var latest=jdbc.queryForList("select * from stock_question_operation where user_id=? and analysis_id=? order by sequence_id desc limit 1",u.toString(),id.toString());root.set("latestAttempt",latest.isEmpty()?m.nullNode():receipt(latest.get(0),now));return root;}
 private void owned(UUID u,UUID id){if(jdbc.queryForObject("select count(*) from stock_analysis_result where analysis_id=? and user_id=?",Integer.class,id.toString(),u.toString())!=1)throw missing();}
 private List<Map<String,Object>> ops(UUID op){return jdbc.queryForList("select * from stock_question_operation where operation_id=?",op.toString());}
 private void check(Map<String,Object> r,UUID u,QuestionInput in){if(!u.toString().equals(r.get("user_id")))throw missing();if(!hash(in).equals(r.get("request_hash")))throw conflict();}
 private JsonNode receipt(Map<String,Object> r,Instant now){var n=m.createObjectNode();for(var pair:List.of(new String[]{"operation_id","operationId"},new String[]{"analysis_id","analysisId"},new String[]{"question","question"},new String[]{"state","state"},new String[]{"answer_id","answerId"},new String[]{"error_code","errorCode"})){Object v=r.get(pair[0]);if(v==null)n.putNull(pair[1]);else n.put(pair[1],v.toString());}return n.put("leaseUntil",instant(r.get("lease_until")).toString()).put("expired","RUNNING".equals(r.get("state"))&&!now.isBefore(instant(r.get("lease_until"))));}
 private JsonNode result(Map<String,Object> r){var n=m.createObjectNode();for(var pair:List.of(new String[]{"answer_id","answerId"},new String[]{"analysis_id","analysisId"},new String[]{"question","question"},new String[]{"status","status"},new String[]{"topic","topic"},new String[]{"context_hash","contextHash"}))n.put(pair[1],r.get(pair[0]).toString());n.put("createdAt",instant(r.get("created_at")).toString());try{n.set("context",m.readTree(r.get("context_json").toString()));n.set("paragraphs",m.readTree(r.get("paragraphs_json").toString()));return n;}catch(Exception e){throw QuestionFacts.invalid();}}
 private String hash(QuestionInput in){return sha(json(List.of(in.analysisId().toString(),in.question())).getBytes(StandardCharsets.UTF_8));}
 private String sha(byte[] v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v));}catch(Exception e){throw QuestionFacts.invalid();}}
 private String json(Object v){try{return m.writeValueAsString(v);}catch(Exception e){throw QuestionFacts.invalid();}}
 private BusinessException missing(){return new BusinessException("RESOURCE_NOT_FOUND","未找到本人问答记录",HttpStatus.NOT_FOUND);}
 private BusinessException conflict(){return new BusinessException("AI_REQUEST_CONFLICT","请求编号与问题或分析不一致",HttpStatus.CONFLICT);}
}
